public class Main {
    public static void printTotalPrice(double price, double taxRate) {
        double total = price + (price * taxRate);
        System.out.println("Total: $" + total);
    }

    public static void main(String[] args) {
        printTotalPrice(100.0, 0.05);
    }
}

