practiceProblems.solutionCode:
public class Main {
    public static void printCharPattern(char ch, int count) {
        for (int i = 0; i < count; i++) {
            System.out.print(ch);
        }
        System.out.println();
    }

    public static void main(String[] args) {
        printCharPattern('*', 10);
    }
}

