public class Main {
    public static void printStudentAverage(String name, int score1, int score2, int score3) {
        double avg = (score1 + score2 + score3) / 3.0;
        System.out.println("Student: " + name + " | Average: " + avg);
    }

    public static void main(String[] args) {
        printStudentAverage("Sophia", 85, 90, 95);
    }
}

