practiceProblems.solutionCode:
public class Main {
    public static double calculateKineticEnergy(double massKg, double velocityMs) {
        return 0.5 * massKg * velocityMs * velocityMs;
    }

    public static void main(String[] args) {
        double energy = calculateKineticEnergy(2, 10);
        System.out.println("Kinetic Energy: " + energy + " J");
    }
}
